SELECT DATE_TRUNC('WEEK', started_at) AS week_start, customer_id, DATE_TRUNC('YEAR', started_at) AS year_start, SIZE(COLLECT_SET(country)) AS num_countries, COUNT_IF(device = 'desktop') AS desktop_events, MIN(started_at) AS started_at, MIN(started_at) AS started_at_2, MAX(started_at) AS last_seen FROM sessions GROUP BY DATE_TRUNC('WEEK', started_at), customer_id, DATE_TRUNC('YEAR', started_at) HAVING SIZE(COLLECT_SET(country)) > 1 ORDER BY num_countries DESC
